<?php require_once __DIR__ . '/_boot.php'; $rows=[]; try { $st=db()->prepare("SELECT p.id,p.name,p.base_unit,COALESCE(SUM(sl.qty_in-sl.qty_out),0) stock, COALESCE(p.reorder_level,0) reorder_level FROM products p LEFT JOIN stock_ledger sl ON sl.product_id=p.id AND sl.branch_id=? WHERE COALESCE(p.track_stock,1)=1 GROUP BY p.id,p.name,p.base_unit,p.reorder_level ORDER BY p.name LIMIT 500"); $st->execute([$unitId]); $rows=$st->fetchAll(PDO::FETCH_ASSOC)?:[]; } catch(Throwable $e) { $err=$e->getMessage(); } ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stok Dapur</title><link rel="icon" href="<?php echo e(favicon_url()); ?>"><link rel="stylesheet" href="<?php echo e(asset_url('assets/app.css')); ?>"><style><?php echo $customCss; ?></style></head><body><div class="container"><?php include __DIR__ . '/_sidebar.php'; ?><div class="main"><div class="topbar"><button class="btn" data-toggle-sidebar type="button">Menu</button><strong>Stok Dapur</strong></div><div class="content"><div class="card"><table class="table"><thead><tr><th>Produk</th><th>Stok</th><th>Reorder</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): $low=((float)$r['reorder_level']>0 && (float)$r['stock'] <= (float)$r['reorder_level']); ?><tr><td><?php echo e($r['name']); ?></td><td><?php echo e(format_qty($r['stock'],$r['base_unit'])); ?></td><td><?php echo e(format_qty($r['reorder_level'],$r['base_unit'])); ?></td><td><?php echo $low ? 'Stok rendah' : 'Aman'; ?></td></tr><?php endforeach; if(empty($rows)): ?><tr><td colspan="4">Belum ada data stok.</td></tr><?php endif; ?></tbody></table></div></div></div></div><script src="<?php echo e(asset_url('assets/app.js')); ?>"></script></body></html>
